import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, color, float, length, oneMinus } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, CylinderGeometry, DirectionalLight, PointLight, Box3, Vector3 } = THREE;

  const group = new Group();
  group.name = 'orbit-product-hero';

  const timelines = [];
  const primitiveHandles = [];
  const disposables = [];

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };
  const gradientStops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.55, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];

  // ------------------------------------------------------------------
  // 1. BACKDROP — engineered vertical gradient, 7x6 at z=-2.5
  // ------------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const t = uv().y;
    const c0 = color(gradientStops[0].hex);
    const c1 = color(gradientStops[1].hex);
    const c2 = color(gradientStops[2].hex);
    const a1 = float(gradientStops[1].at);
    const lower = mix(c0, c1, smoothstep(float(0.0), a1, t));
    const full = mix(lower, c2, smoothstep(a1, float(1.0), t));
    // subtle vignette lift behind subject so metal has a value to sit against
    const centerDist = length(uv().sub(vec3(0.5, 0.55, 0.0).xy));
    const lift = oneMinus(smoothstep(float(0.12), float(0.75), centerDist)).mul(0.06);
    backdropMat.colorNode = full.add(vec3(lift, lift, lift.mul(1.15)));
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ------------------------------------------------------------------
  // 2. SUBJECT GROUP (watch + plinth + contact shadow) — orbits together
  // ------------------------------------------------------------------
  const subject = new Group();
  subject.name = 'subject';
  subject.position.set(0, 0.35, 0);
  group.add(subject);

  // Plinth: low cylinder, top face at y=-1.1 relative to subject center offset
  const plinthGeo = new CylinderGeometry(1.4, 1.45, 0.25, 64);
  const plinthMat = new MeshStandardNodeMaterial();
  plinthMat.color = new THREE.Color(colors.surface ?? '#14141a');
  plinthMat.roughness = 0.7;
  plinthMat.metalness = 0.3;
  const plinth = new Mesh(plinthGeo, plinthMat);
  plinth.position.set(0, -1.225, 0); // top face at y = -1.1
  subject.add(plinth);
  disposables.push(plinthGeo, plinthMat);

  // Contact shadow: radial gradient plane under plinth
  const shadowGeo = new PlaneGeometry(3.2, 3.2);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  {
    const d = length(uv().sub(vec3(0.5, 0.5, 0.0).xy)).mul(2.0);
    const alpha = oneMinus(smoothstep(float(0.15), float(1.0), d)).mul(0.55);
    shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
    shadowMat.opacityNode = alpha;
  }
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -1.345, 0);
  contactShadow.renderOrder = 1;
  subject.add(contactShadow);
  disposables.push(shadowGeo, shadowMat);

  // Watch mesh — loaded async, normalized to 2.2 units tall, resting on plinth
  const watchHolder = new Group();
  watchHolder.name = 'watch-holder';
  subject.add(watchHolder);

  const watchMaterial = new MeshPhysicalNodeMaterial();
  watchMaterial.color = new THREE.Color(colors.paper ?? '#e8ecf2');
  watchMaterial.roughness = 0.52;
  watchMaterial.metalness = 0.55;
  watchMaterial.clearcoat = 0.2;
  watchMaterial.clearcoatRoughness = 0.4;
  watchMaterial.anisotropy = 0.8;
  disposables.push(watchMaterial);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const model = gltf.scene;
      // Normalize: 2.2 units tall, centered, base at plinth top (y=-1.1)
      const box = new Box3().setFromObject(model);
      const size = new Vector3();
      box.getSize(size);
      const scale = 2.2 / Math.max(size.y, 1e-6);
      model.scale.setScalar(scale);
      const box2 = new Box3().setFromObject(model);
      const center = new Vector3();
      box2.getCenter(center);
      model.position.x -= center.x;
      model.position.z -= center.z;
      model.position.y -= box2.min.y; // base to y=0 of holder
      watchHolder.position.y = -1.1;  // holder base sits on plinth top

      model.traverse((child) => {
        if (child.isMesh) {
          // If GLB carries no textured material, apply the machined-titanium PBR
          const hasMap = child.material && child.material.map;
          if (!hasMap) {
            child.material = watchMaterial;
          } else {
            child.material.roughness = 0.52;
            child.material.metalness = 0.55;
          }
        }
      });
      watchHolder.add(model);

      // Entrance: weighted rise + settle overshoot
      watchHolder.scale.setScalar(0.96);
      const entrance = gsap.timeline();
      entrance.fromTo(
        watchHolder.position,
        { y: -1.1 - 0.35 },
        { y: -1.1, duration: 0.7, ease: 'power3.out' },
        0
      );
      entrance.to(
        watchHolder.scale,
        { x: 1.04, y: 1.04, z: 1.04, duration: 0.35, ease: 'power2.out' },
        0.15
      );
      entrance.to(
        watchHolder.scale,
        { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
        0.5
      );
      timelines.push(entrance);
    });
  }

  // ------------------------------------------------------------------
  // 3. LIGHTING — accent rim on left flank, cool fill from right rear.
  // Scene supplies ambient 0.6 + key 1.2; add node-local rim only.
  // ------------------------------------------------------------------
  const accentRim = new DirectionalLight(new THREE.Color(colors.accent ?? '#ff2a38'), 1.4);
  accentRim.position.set(-3.2, 0.6, -1.6);
  accentRim.target = subject;
  group.add(accentRim);

  const backFill = new PointLight(new THREE.Color(colors.paper ?? '#e8ecf2'), 0.7, 12, 2);
  backFill.position.set(2.4, 1.8, -1.2);
  group.add(backFill);

  // ------------------------------------------------------------------
  // 4. TEXT — verbatim from spec, bimodal scale, ASCII only
  // ------------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  textGroup.name = 'copy';
  group.add(textGroup);

  const roleLayout = {
    headline: { y: -1.5, fontSize: 68, color: colors.paper ?? '#e8ecf2', ls: 0 },
    body: { y: -2.0, fontSize: 26, color: colors.paper ?? '#e8ecf2', ls: 0 },
    caption: { y: -2.4, fontSize: 18, color: colors.accent ?? '#ff2a38', ls: 1.5 },
  };

  for (const item of items) {
    const role = item.role ?? 'body';
    const layout = roleLayout[role] ?? roleLayout.body;
    const textObj = ctx.fontAtlas.createText(String(item.text), {
      fontSize: item.typography?.fontSize ?? layout.fontSize,
      color: layout.color,
      align: 'center',
      letterSpacingPx: layout.ls,
    });
    textObj.position.set(0, layout.y, 0.4);
    textGroup.add(textObj);
  }

  // Text entrance: fade-up rhythm
  const textTl = gsap.timeline();
  textGroup.children.forEach((child, i) => {
    textTl.fromTo(
      child.position,
      { y: child.position.y - 0.2 },
      { y: child.position.y, duration: 0.5, ease: 'power2.out' },
      0.25 + i * 0.08
    );
  });
  timelines.push(textTl);

  // ------------------------------------------------------------------
  // 5. CINEMATIC PRIMITIVES — applied via ctx.primitives, never inlined
  // ------------------------------------------------------------------
  const prims = config.cinematicPrimitives ?? [];
  for (const primitive of prims) {
    const fn = ctx.primitives[primitive.name];
    if (fn) {
      const handle = fn(subject, primitive.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ------------------------------------------------------------------
  // 6. EVENT HANDLERS — hover settle uses weighted overshoot
  // ------------------------------------------------------------------
  group.userData.handlers = {
    pointerover: () => {
      gsap.to(subject.scale, {
        x: 1.02,
        y: 1.02,
        z: 1.02,
        duration: 0.3,
        ease: 'power2.out',
      });
    },
    pointerout: () => {
      const settle = gsap.timeline();
      settle.to(subject.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.25, ease: 'power2.out' }, 0);
      settle.to(subject.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.25);
      timelines.push(settle);
    },
    click: () => {
      gsap.fromTo(
        subject.scale,
        { x: 0.97, y: 0.97, z: 0.97 },
        { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out(2)' }
      );
      ctx.emit('hero:select', { id: 'calibre-na-01' });
    },
  };

  // ------------------------------------------------------------------
  // 7. CLEANUP
  // ------------------------------------------------------------------
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    primitiveHandles.forEach((h) => {
      if (h && typeof h.cleanup === 'function') h.cleanup();
      if (h && h.timeline && typeof h.timeline.kill === 'function') h.timeline.kill();
    });
    gsap.killTweensOf(subject.scale);
    gsap.killTweensOf(subject.rotation);
    gsap.killTweensOf(watchHolder.position);
    gsap.killTweensOf(watchHolder.scale);
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
    group.traverse((child) => {
      if (child.isMesh) {
        if (child.geometry && typeof child.geometry.dispose === 'function') child.geometry.dispose();
        if (child.material && typeof child.material.dispose === 'function') child.material.dispose();
      }
    });
  };

  return group;
}
